def separateSquares(squares):
    lo = min(y for x, y, l in squares)
    hi = max(y + l for x, y, l in squares)
    total = sum(l * l for x, y, l in squares)
    half = total / 2.0

    def below(Y):
        s = 0.0
        for x, y, l in squares:
            if Y >= y + l:
                s += l * l
            elif Y > y:
                s += l * (Y - y)
        return s

    for _ in range(100):
        mid = (lo + hi) / 2.0
        if below(mid) >= half:
            hi = mid
        else:
            lo = mid
    return hi
